// ──────────────────────────── tests ──────────────────────────────────────

test('page 1 is the first slice, not the second', () => {
  eq(paginate(ROWS, 1, 5).items, ROWS.slice(0, 5));
});

test('page 2 starts exactly where page 1 stopped', () => {
  eq(paginate(ROWS, 2, 5).items, ROWS.slice(5, 10));
});

test('the last page holds the remainder', () => {
  const last = paginate(ROWS, 3, 5);
  eq(last.items, ['row-11', 'row-12', 'row-13']);
  eq(last.hasNext, false);
});

test('totalPages rounds up and totals ignore the page asked for', () => {
  eq(paginate(ROWS, 1, 5).totalPages, 3);
  eq(paginate(ROWS, 1, 13).totalPages, 1);
  eq(paginate(ROWS, 1, 4).totalPages, 4);
  eq(paginate(ROWS, 2, 5).totalItems, 13);
});

test('page numbers outside the range are clamped', () => {
  eq(paginate(ROWS, 0, 5).page, 1);
  eq(paginate(ROWS, 99, 5).page, 3);
  eq(paginate(ROWS, 0, 5).hasPrev, false);
  eq(paginate(ROWS, 99, 5).hasNext, false);
});

test('walking every page visits every row exactly once', () => {
  const seen = [];
  const pages = paginate(ROWS, 1, 5).totalPages;
  for (let p = 1; p <= pages; p++) {
    seen.push(...paginate(ROWS, p, 5).items);
  }
  eq(seen, ROWS);
});

test('a perPage bigger than the list gives one full page', () => {
  eq(paginate(ROWS, 1, 50).items, ROWS);
  eq(paginate([], 1, 5).items, []);
  eq(paginate([], 1, 5).totalPages, 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('drops a single expired session', () => {
  eq(ids(purgeExpired(makeSessions(), 150)), ['s2', 's3', 's4', 's5']);
});

test('keeps everything when nothing has expired yet', () => {
  eq(ids(purgeExpired(makeSessions(), 50)), ['s1', 's2', 's3', 's4', 's5']);
  eq(purgeExpired([], 999), []);
});

test('drops a run of two expired sessions sitting side by side', () => {
  eq(ids(purgeExpired(makeSessions(), 500)), ['s2', 's5']);
});

test('mutates the array it was handed and returns that same array', () => {
  const live = makeSessions();
  const out = purgeExpired(live, 150);
  ok(out === live, 'should return the same array object, not a copy');
  eq(ids(live), ['s2', 's3', 's4', 's5']);
});

test('an expiry exactly at now counts as expired', () => {
  const list = [
    { id: 'a', expiresAt: 500 },
    { id: 'b', expiresAt: 501 },
  ];
  eq(ids(purgeExpired(list, 500)), ['b']);
});

test('purging a fully expired list leaves it empty', () => {
  eq(ids(purgeExpired(makeSessions(), 900)), []);
});

test('the survivors keep their original order', () => {
  eq(ids(purgeExpired(makeSessions(), 250)), ['s2', 's4', 's5']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('makeBoard has the shape you asked for', () => {
  const board = makeBoard(3, 4);
  eq(board.length, 3);
  eq(board.map((row) => row.length), [4, 4, 4]);
});

test('a fresh board is nothing but the fill value', () => {
  eq(render(makeBoard(3, 4)), '....\n....\n....');
  eq(render(makeBoard(2, 2, '0')), '00\n00');
});

test('place marks exactly one cell', () => {
  const board = makeBoard(3, 4);
  place(board, 1, 2, 'X');
  eq(render(board), '....\n..X.\n....');
});

test('two marks land on the two cells you named', () => {
  const board = makeBoard(2, 2);
  place(board, 0, 0, 'X');
  place(board, 1, 1, 'O');
  eq(render(board), 'X.\n.O');
});

test('place refuses coordinates that are off the board', () => {
  const board = makeBoard(2, 2);
  throws(() => place(board, 2, 0, 'X'), 'off the board');
  throws(() => place(board, 0, 5, 'X'), 'off the board');
  throws(() => place(board, -1, 0, 'X'), 'off the board');
});

test('boards from separate calls never share cells', () => {
  const first = makeBoard(2, 2);
  const second = makeBoard(2, 2);
  place(first, 0, 0, 'X');
  eq(render(second), '..\n..');
});

test('each row is its own array', () => {
  const board = makeBoard(3, 3);
  ok(board[0] !== board[1], 'row 0 and row 1 should be different arrays');
  ok(board[1] !== board[2], 'row 1 and row 2 should be different arrays');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('drops undefined, null and the empty string', () => {
  eq(compactParams({ a: 1, b: undefined, c: null, d: '' }), { a: 1 });
});

test('keeps a zero, because 0 is a page number', () => {
  eq(compactParams({ page: 0, q: 'x' }), { page: 0, q: 'x' });
});

test('keeps false, because false is an answer', () => {
  eq(compactParams({ archived: false, sort: 'name' }), {
    archived: false,
    sort: 'name',
  });
});

test('keeps strings that only look empty', () => {
  eq(compactParams({ id: '0', note: ' ', flag: 'false' }), {
    id: '0',
    note: ' ',
    flag: 'false',
  });
});

test('leaves the object it was given untouched', () => {
  const input = { a: 1, b: null };
  compactParams(input);
  eq(input, { a: 1, b: null });
});

test('toQuery encodes and joins the surviving params', () => {
  eq(toQuery({ q: 'a b', page: 0 }), '?q=a%20b&page=0');
  eq(toQuery({ q: 'ada', tag: '', cursor: null }), '?q=ada');
});

test('nothing worth sending gives an empty query string', () => {
  eq(compactParams({}), {});
  eq(toQuery({ a: '', b: null, c: undefined }), '');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('players who have not played are left off the board', () => {
  const names = leaderboard(PLAYERS).map((row) => row.name);
  eq(names.includes('fin'), false);
  eq(names.length, 5);
});

test('rank 1 is the highest score on the board', () => {
  const top = leaderboard(PLAYERS)[0];
  eq(top.name, 'bo');
  eq(top.score, 91);
});

test('the whole board runs from highest score to lowest', () => {
  eq(leaderboard(PLAYERS).map((row) => row.name), [
    'bo',
    'cy',
    'eve',
    'ada',
    'dee',
  ]);
});

test('a tie is broken by name, A to Z', () => {
  const tied = [
    { name: 'cy', score: 91, games: 10 },
    { name: 'bo', score: 91, games: 7 },
  ];
  eq(leaderboard(tied).map((row) => row.name), ['bo', 'cy']);
});

test('ranks are 1-based and follow the board order', () => {
  eq(leaderboard(PLAYERS).map((row) => row.rank), [1, 2, 3, 4, 5]);
});

test('avg is score per game, rounded to two decimals', () => {
  const byName = new Map(leaderboard(PLAYERS).map((r) => [r.name, r.avg]));
  eq(byName.get('ada'), 7);
  eq(byName.get('cy'), 9.1);
  eq(byName.get('bo'), 13);
});

test('topN takes the best n names', () => {
  eq(topN(PLAYERS, 3), ['bo', 'cy', 'eve']);
  eq(topN(PLAYERS, 1), ['bo']);
});

test('an empty roster produces an empty board', () => {
  eq(leaderboard([]), []);
  eq(topN([], 3), []);
  ok(Array.isArray(leaderboard(PLAYERS)));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('each order gets a total of its own lines', () => {
  eq(rollUp(ORDERS).orders, [
    { id: 'o1', totalCents: 14700 },
    { id: 'o2', totalCents: 58700 },
    { id: 'o3', totalCents: 0 },
  ]);
});

test('categories are summed across every order', () => {
  eq(rollUp(ORDERS).byCategory, {
    input: 35600,
    adapter: 5800,
    display: 32000,
  });
});

test('the grand total counts every line of every order', () => {
  eq(rollUp(ORDERS).totalCents, 73400);
});

test('the grand total equals the per-order totals added up', () => {
  const report = rollUp(ORDERS);
  const sum = report.orders.reduce((acc, o) => acc + o.totalCents, 0);
  eq(report.totalCents, sum);
});

test('the grand total equals the category totals added up', () => {
  const report = rollUp(ORDERS);
  const sum = Object.values(report.byCategory).reduce((a, b) => a + b, 0);
  eq(report.totalCents, sum);
});

test('no orders at all rolls up to zeros', () => {
  eq(rollUp([]), { totalCents: 0, orders: [], byCategory: {} });
});

test('an order with no items still gets a row worth nothing', () => {
  eq(rollUp([{ id: 'x', items: [] }]), {
    totalCents: 0,
    orders: [{ id: 'x', totalCents: 0 }],
    byCategory: {},
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('one validator per rule, labelled and ordered', () => {
  const validators = makeValidators(RULES);
  eq(validators.map((v) => v.field), ['username', 'email', 'password']);
  eq(validators.map((v) => v.order), [1, 2, 3]);
});

test('a form that satisfies every rule reports nothing', () => {
  const form = { username: 'ada', email: 'a@b.io', password: 'hunter22!' };
  eq(validate(form, makeValidators(RULES)), []);
});

test('a short username is reported by name', () => {
  const form = { username: 'ad', email: 'a@b.io', password: 'hunter22!' };
  eq(validate(form, makeValidators(RULES)), [
    'username needs at least 3 characters',
  ]);
});

test('every broken rule gets its own message, in rule order', () => {
  const blank = { username: '', email: '', password: '' };
  eq(validate(blank, makeValidators(RULES)), [
    'username needs at least 3 characters',
    'email needs at least 6 characters',
    'password needs at least 8 characters',
  ]);
});

test('a missing field counts as empty and is still named', () => {
  const form = { username: 'ada', password: 'hunter22!' };
  eq(validate(form, makeValidators(RULES)), [
    'email needs at least 6 characters',
  ]);
});

test('a validator can be pulled out and called on its own', () => {
  const [, emailCheck] = makeValidators(RULES);
  eq(emailCheck.check({ email: 'x' }), 'email needs at least 6 characters');
  eq(emailCheck.check({ email: 'ada@b.io' }), null);
});

test('a satisfied rule returns null, not a message', () => {
  const validators = makeValidators(RULES);
  eq(validators[2].check({ password: 'hunter22!' }), null);
});

test('no rules means no validators and nothing to report', () => {
  eq(makeValidators([]), []);
  eq(validate({ username: '' }, makeValidators([])), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('add chains and records entries in order', () => {
  const ledger = new Ledger().add('coffee', 450).add('refund', -200);
  ok(ledger instanceof Ledger, 'add should return the ledger');
  eq(ledger.entries, [
    { label: 'coffee', cents: 450 },
    { label: 'refund', cents: -200 },
  ]);
  throws(() => ledger.add('bad', 4.5), 'whole cents');
});

test('format renders one amount with the ledger symbol', () => {
  const ledger = new Ledger('USD');
  eq(ledger.format(450), '$4.50');
  eq(ledger.format(-200), '-$2.00');
  eq(ledger.format(0), '$0.00');
});

test('totalCents adds every entry up', () => {
  const ledger = new Ledger().add('coffee', 450).add('refund', -200);
  eq(ledger.totalCents, 250);
  eq(new Ledger().totalCents, 0);
});

test('receipt lists every entry and then the total', () => {
  const ledger = new Ledger().add('coffee', 450).add('refund', -200);
  eq(ledger.receipt(), 'coffee: $4.50\nrefund: -$2.00\ntotal: $2.50');
});

test('formatAll formats every entry', () => {
  const ledger = new Ledger().add('coffee', 450).add('bagel', 325);
  eq(ledger.formatAll(), ['$4.50', '$3.25']);
});

test('formatAll keeps the sign on a refund', () => {
  const ledger = new Ledger().add('refund', -200).add('fee', 99);
  eq(ledger.formatAll(), ['-$2.00', '$0.99']);
});

test('a ledger in another currency uses its own symbol everywhere', () => {
  const ledger = new Ledger('EUR').add('book', 1250);
  eq(ledger.format(1250), '€12.50');
  eq(ledger.formatAll(), ['€12.50']);
  eq(ledger.receipt(), 'book: €12.50\ntotal: €12.50');
});

test('an empty ledger formats to nothing at all', () => {
  const ledger = new Ledger();
  eq(ledger.formatAll(), []);
  eq(ledger.receipt(), 'total: $0.00');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('toCents lands on the cent a human would write down', () => {
  eq(toCents(1.15), 115);
  eq(toCents(0.29), 29);
  eq(toCents(19.99), 1999);
  eq(toCents(0), 0);
});

test('formatUsd pads the cents and keeps the sign', () => {
  eq(formatUsd(1799), '$17.99');
  eq(formatUsd(5), '$0.05');
  eq(formatUsd(0), '$0.00');
  eq(formatUsd(-501), '-$5.01');
});

test('a line multiplies whole cents, never dollars', () => {
  eq(lineCents({ unitPrice: 1.1, quantity: 3 }), 330);
  eq(lineCents({ unitPrice: 19.99, quantity: 2 }), 3998);
  eq(subtotalCents([...SNACKS, ...DESK]), 2329);
});

test('tax rounds to the nearest cent', () => {
  eq(taxCents(1999, 0.0825), 165);
  eq(invoiceCents(DESK, 0.0825), 2164);
  eq(invoiceCents(DESK, 0), 1999);
});

test('a partial payment leaves an exact positive balance', () => {
  const result = settle(DESK, 0, [15, 4.75]);
  eq(result.paidCents, 1975);
  eq(result.balanceCents, 24);
  eq(result.settled, false);
});

test('an overpayment reports a negative balance, not a settlement', () => {
  const result = settle(DESK, 0, [25]);
  eq(result.balanceCents, -501);
  eq(result.settled, false);
});

test('payments in awkward dollars still total a whole number of cents', () => {
  const result = settle(SNACKS, 0, [1.1, 2.2]);
  ok(Number.isInteger(result.paidCents), 'paidCents must be an integer');
  eq(result.paidCents, 330);
});

test('$1.10 plus $2.20 settles a $3.30 invoice', () => {
  const result = settle(SNACKS, 0, [1.1, 2.2]);
  eq(result.balanceCents, 0);
  eq(result.settled, true);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('fetchAll returns rows in the order they were asked for', async () => {
  const fetchRow = makeWarehouse(STOCK);
  const rows = await fetchAll(['clips', 'ink'], fetchRow);
  eq(rows.map((row) => row.sku), ['clips', 'ink']);
});

test('an unknown sku rejects instead of returning a hole', async () => {
  const fetchRow = makeWarehouse(STOCK);
  await rejects(() => fetchAll(['ink', 'nope'], fetchRow), 'unknown sku');
});

test('the reorder rules read straight off the row', () => {
  eq(needsRestock(STOCK.ink), true);
  eq(needsRestock(STOCK.toner), false);
  eq(orderQuantity(STOCK.ink), 11);
  eq(orderQuantity(STOCK.paper), 16);
});

test('the report counts every row it looked at', async () => {
  const fetchRow = makeWarehouse(STOCK);
  const placeOrder = async (sku) => `ord-${sku}`;
  const report = await restock(SKUS, fetchRow, placeOrder);
  eq(report.checked, 4);
  eq(report.skipped, 2);
});

test('one order goes out per low row, with the right quantity', async () => {
  const fetchRow = makeWarehouse(STOCK);
  const placeOrder = spy(async (sku) => `ord-${sku}`);
  await restock(SKUS, fetchRow, placeOrder);
  eq(placeOrder.callCount, 2);
  eq(placeOrder.calls, [['paper', 16], ['ink', 11]]);
});

test('every order has come back before the report resolves', async () => {
  const fetchRow = makeWarehouse(STOCK);
  let confirmed = 0;
  const placeOrder = async (sku) => {
    await sleep(3);
    confirmed += 1;
    return `ord-${sku}`;
  };
  await restock(SKUS, fetchRow, placeOrder);
  eq(confirmed, 2);
});

test('the report lists the orders it placed', async () => {
  const fetchRow = makeWarehouse(STOCK);
  const placeOrder = async (sku) => {
    await sleep(3);
    return `ord-${sku}`;
  };
  const report = await restock(SKUS, fetchRow, placeOrder);
  eq(report.placed.length, 2);
  eq(report.placed.map((order) => order.sku).sort(), ['ink', 'paper']);
  ok(report.placed.every((order) => order.orderId.startsWith('ord-')));
});

test('the report totals the units it ordered', async () => {
  const fetchRow = makeWarehouse(STOCK);
  const placeOrder = async (sku) => `ord-${sku}`;
  const report = await restock(SKUS, fetchRow, placeOrder);
  eq(report.unitsOrdered, 27);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a clean file becomes typed rows and reports ok', () => {
  const report = importCsv(CLEAN);
  eq(report.headers, ['sku', 'qty', 'price']);
  eq(report.rows.length, 3);
  eq(report.rows[0], { sku: 'desk-01', qty: 2, price: 1999 });
  eq(report.ok, true);
  eq(report.errors, []);
});

test('blank lines are skipped without becoming errors', () => {
  eq(importCsv(CLEAN).errors, []);
  eq(importCsv(CLEAN).rows.at(-1), { sku: 'lamp-3', qty: 4, price: 1200 });
});

test('a ragged row is reported with its line number, not thrown', () => {
  const report = importCsv(RAGGED);
  eq(report.errors[0], { line: 3, message: 'expected 3 columns, got 2' });
  eq(report.ok, false);
});

test('a cell that fails to coerce is reported too', () => {
  const report = importCsv(RAGGED);
  eq(report.errors.length, 2);
  eq(report.errors[1], { line: 4, message: 'bad qty: many' });
});

test('rows that failed never show up as successes', () => {
  const report = importCsv(RAGGED);
  eq(report.rows.map((row) => row.sku), ['desk-01']);
});

test('a failure the importer does not recognise is not swallowed', () => {
  throws(() => importCsv(PRICED_IN_GBP, coerceWithCurrency),
    'no such currency: GBP');
});

test('a broken coercer fails loudly instead of importing nothing', () => {
  throws(() => importCsv(CLEAN, null), 'not a function');
  const report = importCsv(CLEAN);
  ok(report.rows.length > 0, 'the clean file still imports normally');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the raw check is a plain lookup', () => {
  eq(checkGrant('12', '345'), true);
  eq(checkGrant('123', '45'), false);
  eq(checkGrant('7', '88'), true);
});

test('a repeated lookup is answered from the cache', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  eq(memo('12', '345'), true);
  eq(memo('12', '345'), true);
  eq(source.callCount, 1);
  eq(memo.stats(), { hits: 1, misses: 1, size: 1 });
});

test('unrelated argument lists each reach the source', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  eq(memo('7', '88'), true);
  eq(memo('7', '89'), true);
  eq(memo('9', '88'), false);
  eq(source.callCount, 3);
  eq(memo.stats().size, 3);
});

test('invalidate makes the next call reach the source again', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  memo('7', '88');
  memo('7', '88');
  memo.invalidate();
  eq(memo('7', '88'), true);
  eq(source.callCount, 2);
});

test('two memoized functions do not share a cache', () => {
  const first = spy(checkGrant);
  const second = spy(checkGrant);
  const memoFirst = memoize(first);
  const memoSecond = memoize(second);
  memoFirst('7', '88');
  memoSecond('7', '88');
  eq(first.callCount, 1);
  eq(second.callCount, 1);
});

test('arguments that split differently are different lookups', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  eq(memo('12', '345'), true);
  eq(memo('123', '45'), false);
  eq(source.callCount, 2);
});

test('how many arguments arrived is part of the identity', () => {
  const countArgs = spy((...parts) => parts.length);
  const memo = memoize(countArgs);
  eq(memo('a', 'b'), 2);
  eq(memo('ab'), 1);
  eq(countArgs.callCount, 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('lowerBound stops at the first copy of a repeated value', () => {
  eq(lowerBound(REPEATS, 2), 1);
  eq(lowerBound(REPEATS, 1), 0);
  eq(lowerBound(NUMBERS, 3), 1);
});

test('a value that is missing gives the index it would go in', () => {
  eq(lowerBound(NUMBERS, 4), 2);
  eq(lowerBound(NUMBERS, 0), 0);
  eq(lowerBound(NUMBERS, 6), 3);
  eq(lowerBound([], 5), 0);
  eq(upperBound([], 5), 0);
});

test('upperBound stops one past the last copy', () => {
  eq(upperBound(REPEATS, 2), 4);
  eq(upperBound(NUMBERS, 1), 1);
  eq(upperBound(NUMBERS, 4), 2);
});

test('contains says yes only when the value is really there', () => {
  eq(contains(NUMBERS, 5), true);
  eq(contains(NUMBERS, 7), true);
  eq(contains(NUMBERS, 4), false);
  eq(contains(NUMBERS, 9), false);
  eq(contains([], 1), false);
});

test('a value bigger than everything lands past the end', () => {
  eq(lowerBound(NUMBERS, 9), 4);
  eq(upperBound(NUMBERS, 7), 4);
  eq(upperBound(REPEATS, 5), 5);
});

test('countInRange counts an inclusive window', () => {
  eq(countInRange(NUMBERS, 3, 5), 2);
  eq(countInRange(NUMBERS, 0, 2), 1);
  eq(countInRange(REPEATS, 2, 2), 3);
});

test('countInRange still counts a window that reaches the last value', () => {
  eq(countInRange(NUMBERS, 5, 7), 2);
  eq(countInRange(NUMBERS, 1, 7), 4);
  eq(countInRange(REPEATS, 2, 5), 4);
});

test('insertInOrder drops the value into the right slot', () => {
  eq(insertInOrder(NUMBERS, 4), [1, 3, 4, 5, 7]);
  eq(insertInOrder(NUMBERS, 0), [0, 1, 3, 5, 7]);
  eq(insertInOrder(REPEATS, 2), [1, 2, 2, 2, 2, 5]);
  eq(insertInOrder(NUMBERS, 9), [1, 3, 5, 7, 9]);
  eq(NUMBERS, [1, 3, 5, 7]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('one query in, its results out', async () => {
  const box = createSearchBox(makeSearchApi(INDEX));
  eq(await box.type('ante'), ['anteater', 'antelope']);
  eq(box.results, ['anteater', 'antelope']);
  eq(box.error, null);
});

test('the value is the last thing typed, before any response', async () => {
  const box = createSearchBox(makeSearchApi(INDEX));
  const inFlight = box.type('ant');
  eq(box.value, 'ant');
  eq(box.pending, 1);
  await inFlight;
  eq(box.pending, 0);
});

test('clearing the box clears the results without a request', async () => {
  const search = spy(makeSearchApi(INDEX));
  const box = createSearchBox(search);
  await box.type('ant');
  eq(search.callCount, 1);
  await box.type('   ');
  eq(box.results, []);
  eq(search.callCount, 1);
});

test('a failed search is recorded instead of crashing the box', async () => {
  const search = async () => {
    await sleep(2);
    throw new Error('search backend is down');
  };
  const box = createSearchBox(search);
