export function makeLock() {
  const waiters = [];
  const lock = {
    held: false,
    async acquire() {
      if (!lock.held) {
        lock.held = true;
        return;
      }
      await new Promise((resolve) => waiters.push(resolve));
    },
    release() {
      const next = waiters.shift();
      if (next) next();
      else lock.held = false;
    },
  };
  return lock;
}

