const M1 = {
  version: 1,
  sql: 'CREATE TABLE users (id INTEGER PRIMARY KEY, email TEXT);',
};
const M2_BROKEN = {
  version: 2,
  sql: `CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT);
