// ─────────────────────────────────────────────────────────────────────────
//  12 · permission cache — SOLUTION                             ★★☆ core
//  run: node 12-cache-key-collision.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough: bug class — cache key collision. `['12','345']` and
//  `['123','45']` both join to '12345', so the second user gets the
//  first user's answer. In a permission cache that is not a stale value,
//  it is an authorization bug: `false` gets served as `true`.
//
//  The tell: a key built by concatenating variable-length parts with
//  nothing between them. Any encoding that is not injective — join(''),
//  `a + b`, `${a}${b}` — can map two different inputs to one key. Ask of
//  every key: can I read the arguments back out of this string?
//
//  The minimal fix: `JSON.stringify(args)`. It is injective for JSON
//  values, it encodes arity (`["ab"]` vs `["a","b"]`) and it keeps `1`
//  and `'1'` apart, which a separator alone does not. `args.join('�')`
//  also passes these tests and is cheaper — fine when you know every
//  argument is a string that cannot contain a NUL.
//
//  The classic wild variant: hoisting `const cache = new Map()` out of
//  `memoize` so every wrapped function shares one cache — the same
//  collision, now across unrelated functions and never invalidated.

import { test, eq, spy } from '../../_lib/check.js';

const GRANTS = new Set(['12:345', '7:88', '7:89']);

export function checkGrant(userId, docId) {
  return GRANTS.has(`${userId}:${docId}`);
}

export function memoize(fn) {
  const cache = new Map();
  let hits = 0;
  let misses = 0;

  const memoized = (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      hits += 1;
      return cache.get(key);
    }
    misses += 1;
    const value = fn(...args);
    cache.set(key, value);
    return value;
  };

  memoized.stats = () => ({ hits, misses, size: cache.size });
  memoized.invalidate = () => {
    cache.clear();
  };
  return memoized;
}

// ──────────────────────────── tests ──────────────────────────────────────

test('the raw check is a plain lookup', () => {
  eq(checkGrant('12', '345'), true);
  eq(checkGrant('123', '45'), false);
  eq(checkGrant('7', '88'), true);
});

test('a repeated lookup is answered from the cache', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  eq(memo('12', '345'), true);
  eq(memo('12', '345'), true);
  eq(source.callCount, 1);
  eq(memo.stats(), { hits: 1, misses: 1, size: 1 });
});

test('unrelated argument lists each reach the source', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  eq(memo('7', '88'), true);
  eq(memo('7', '89'), true);
  eq(memo('9', '88'), false);
  eq(source.callCount, 3);
  eq(memo.stats().size, 3);
});

test('invalidate makes the next call reach the source again', () => {
  const source = spy(checkGrant);
  const memo = memoize(source);
  memo('7', '88');
  memo('7', '88');
  memo.invalidate();
  eq(memo('7', '88'), true);
  eq(source.callCount, 2);
