  const first = spy(checkGrant);
  const second = spy(checkGrant);
  const memoFirst = memoize(first);
  const memoSecond = memoize(second);
  memoFirst('7', '88');
  memoSecond('7', '88');
  eq(first.callCount, 1);
  eq(second.callCount, 1);
